<script setup lang="ts">
import {ref,watch,onMounted,onBeforeUnmount} from 'vue';
import {ApiError,unwrap,mutationHeaders,type components} from '../../api-client/src';
import {StaffSession,explainError} from './auth';
type Schema=components['schemas'];
type Trade=Schema['ServiceTrade'];type Terms=Schema['ServiceTerms'];type Fulfillment=Schema['ServiceTradeFulfillmentInput'];
const props=defineProps<{session:StaffSession;realm:'merchant'|'admin'}>();
const terms=ref<Terms[]>([]),trades=ref<Trade[]>([]),services=ref<Schema['BookingService'][]>([]),ledger=ref<Schema['ServiceTradeLedgerEntry'][]>([]);
const termCursor=ref<string|null>(null),tradeCursor=ref<string|null>(null),ledgerCursor=ref<string|null>(null),serviceCursor=ref<string|null>(null);
const histories=ref<Record<string,Schema['ServiceTradeFulfillmentEvent'][]>>({}),disputes=ref<Record<string,Schema['ServiceTradeDispute'][]>>({}),detailCursors=ref<Record<string,string|null>>({});
const credentials=ref<Record<string,string>>({}),reasons=ref<Record<string,Fulfillment['reason_code']>>({});
const selectedService=ref(''),amount=ref<number|''>(''),cutoff=ref<number|''>(''),rate=ref<number|''>(''),buffer=ref<number|''>(''),scenario=ref(false);
const lookup=ref(''),merchantId=ref(''),password=ref(''),busy=ref(false),error=ref(''),notice=ref('');
const assessment=ref<Schema['RefundAssessment']>(),preview=ref<Schema['ServiceTradeSettlementPreview']>(),reconciliation=ref<Schema['ServiceTradeReconciliation']>();
const keys=new Map<string,string>();let generation=0;const blocked=ref(false);
const labels:Record<string,string>={AWAITING_PAYMENT:'待付款',CONFIRMED:'已确认',CANCELLED:'已取消',EXPIRED:'已关闭',NOT_STARTED:'未到店',CHECKED_IN:'已到店',COMPLETED:'已完成',NO_SHOW:'未到店待评估',EXCEPTION:'异常待处理',NOT_PAYABLE:'不可结算',WAITING_COMPLETION:'等待履约',BUFFERING:'缓冲中',FROZEN:'冻结',ELIGIBLE:'可结算',SETTLED:'已结算',ADJUSTED:'已追加调整',OPEN:'处理中',RESOLVED:'已处理',DRAFT:'待审核',REVIEWED:'已审核',REJECTED:'已拒绝',SERVICE_COLLECTION:'服务收款',SERVICE_COMMISSION:'原条款佣金',SERVICE_REFUND:'服务退款',SERVICE_COMMISSION_REVERSAL:'累计冲佣',SERVICE_SETTLEMENT:'模拟结算',SERVICE_SETTLED_REFUND_ADJUSTMENT:'已结算退款调整依据',CREDIT:'增加',DEBIT:'减少',TERMS_MISSING:'缺少规则',OPEN_DISPUTE:'争议处理中',UNKNOWN_PAYMENT:'收款待确认',UNKNOWN_REFUND:'退款待确认',BUFFER_NOT_DUE:'缓冲未满',NON_POSITIVE_BALANCE:'净额不为正',CROSS_DOMAIN_DEBT:'其他业务有待处理欠款'};
function money(fen:number|null){return fen===null?'暂不可用':`¥${(fen/100).toFixed(2)}`;}
function permissions(){return [...props.session.state.principal?.permissions??[]].sort().join('|');}
function stamp(){const g=generation,s=props.session.state.principal?.session_id,store=props.session.state.storeId,scope=permissions();return()=>g===generation&&s===props.session.state.principal?.session_id&&store===props.session.state.storeId&&scope===permissions();}
function serviceError(e:unknown){if(e instanceof ApiError){const messages:Record<string,string>={BOOKING_SIMULATION_DISABLED:'当前环境未开启服务预约演练。',SERVICE_TRADE_SIMULATION_DISABLED:'当前环境未开启付费服务演练。',SERVICE_PAYMENT_SIMULATION_DISABLED:'当前环境未开启模拟收退款。',SERVICE_REFUND_REVIEW_REQUIRED:'此交易需人工评估，本次未自动发起退款。',SERVICE_FULFILLMENT_FROZEN:'有收退款或争议待处理，暂不能履约。',SERVICE_FULFILLMENT_CONFLICT:'当前时段或履约状态不支持该操作，请核对服务安排。',SERVICE_CREDENTIAL_INVALID:'凭证不匹配或已过期，请核对消费者出示的付费服务凭证。',SERVICE_SETTLEMENT_PREVIEW_STALE:'交易或流水已变，请重新获取并确认预览。',SERVICE_SETTLEMENT_PREVIEW_EXPIRED:'预览已过期，请重新获取并确认。',SERVICE_SETTLEMENT_PREVIEW_USED:'该预览已经执行，请读取最新记录。',SERVICE_SETTLEMENT_BLOCKED:'仍有冻结原因，暂不能结算。',PILOT_PAUSED:'演练已暂停，已有记录会保留。'};const reason=messages[e.code]??(e.status>=500?'服务暂不可用，已有记录会保留，请稍后刷新。':null);if(reason)return reason+(e.requestId?` 请求编号：${e.requestId}`:'');}return explainError(e);}
function reportError(e:unknown){error.value=serviceError(e);if(e instanceof ApiError&&['BOOKING_SIMULATION_DISABLED','SERVICE_TRADE_SIMULATION_DISABLED','SERVICE_PAYMENT_SIMULATION_DISABLED'].includes(e.code)){blocked.value=true;terms.value=[];trades.value=[];ledger.value=[];histories.value={};disputes.value={};credentials.value={};password.value='';assessment.value=undefined;preview.value=undefined;reconciliation.value=undefined;}}
function reset(){generation++;blocked.value=false;terms.value=[];trades.value=[];services.value=[];ledger.value=[];termCursor.value=tradeCursor.value=ledgerCursor.value=serviceCursor.value=null;histories.value={};disputes.value={};detailCursors.value={};credentials.value={};reasons.value={};selectedService.value='';amount.value=cutoff.value=rate.value=buffer.value='';scenario.value=false;lookup.value='';merchantId.value='';password.value='';assessment.value=undefined;preview.value=undefined;reconciliation.value=undefined;error.value='';notice.value='';busy.value=false;keys.clear();}
async function loadServices(more=false){const current=stamp();const r=unwrap(await props.session.client.api.GET('/merchant/stores/{store_id}/booking-services',{params:{path:{store_id:props.session.state.storeId},query:{limit:50,...more&&serviceCursor.value?{cursor:serviceCursor.value}:{}}}}));if(current()){services.value=more?[...services.value,...r.data]:r.data;serviceCursor.value=r.page.next_cursor;}}
async function loadTerms(more=false){const current=stamp(),store=props.session.state.storeId,query={limit:50,...more&&termCursor.value?{cursor:termCursor.value}:{}};
 const r=props.realm==='admin'?unwrap(await props.session.client.api.GET('/admin/service-trade-terms',{params:{query}})):unwrap(await props.session.client.api.GET('/merchant/stores/{store_id}/service-trade-terms',{params:{path:{store_id:store},query}}));if(current()){terms.value=more?[...terms.value,...r.data]:r.data;termCursor.value=r.page.next_cursor;}}
async function loadTrades(more=false){const current=stamp(),store=props.session.state.storeId;if(props.realm==='admin'){if(!lookup.value)return;const r=unwrap(await props.session.client.api.GET('/admin/service-trade-orders/{id}',{params:{path:{id:lookup.value}}}));if(current())trades.value=[r.data];}
 else {const r=unwrap(await props.session.client.api.GET('/merchant/stores/{store_id}/service-trade-orders',{params:{path:{store_id:store},query:{limit:50,...more&&tradeCursor.value?{cursor:tradeCursor.value}:{}}}}));if(current()){trades.value=more?[...trades.value,...r.data]:r.data;tradeCursor.value=r.page.next_cursor;}}}
async function loadLedger(more=false){const current=stamp(),store=props.session.state.storeId;const r=unwrap(await props.session.client.api.GET('/merchant/stores/{store_id}/service-trade-ledger',{params:{path:{store_id:store},query:{limit:50,...more&&ledgerCursor.value?{cursor:ledgerCursor.value}:{}}}}));if(current()){ledger.value=more?[...ledger.value,...r.data]:r.data;ledgerCursor.value=r.page.next_cursor;}}
async function load(){const current=stamp();busy.value=true;blocked.value=false;error.value='';credentials.value={};assessment.value=undefined;
 try{if(props.realm==='merchant'){if(!props.session.state.storeId)return;if(props.session.can('service.terms.write')){await loadServices();await loadTerms();}if(props.session.can('service.trade.read'))await loadTrades();if(props.session.can('service.trade.ledger.read'))await loadLedger();}
 else{if(props.session.can('service.terms.review'))await loadTerms();if(props.session.can('service.trade.admin.read'))await loadTrades();}
 }catch(e){if(current())reportError(e);}finally{if(current())busy.value=false;}}
async function command(fingerprint:string,work:(key:string)=>Promise<unknown>){if(busy.value)return;const current=stamp(),key=keys.get(fingerprint)??crypto.randomUUID();keys.set(fingerprint,key);busy.value=true;error.value='';notice.value='';
 try{await work(key);if(!current())return;keys.delete(fingerprint);if(!fingerprint.startsWith('settle:')){preview.value=undefined;reconciliation.value=undefined;}credentials.value={};histories.value={};disputes.value={};detailCursors.value={};notice.value='已保存，正在读取服务端最新记录。';await load();}catch(e){if(current())reportError(e);}finally{if(current()){busy.value=false;password.value='';}}}
async function verified(action:'service.terms.review'|'service.trade.refund.review'|'service.trade.dispute.review'|'service.trade.settle',work:(proof:string)=>Promise<unknown>){const current=stamp();const proof=await props.session.client.reverify({action,password:password.value});if(!current())throw new ApiError(401,'SESSION_CHANGED','');return work(proof.reverify_token);}
async function draft(){if(!scenario.value||!selectedService.value||[amount.value,cutoff.value,rate.value,buffer.value].some(n=>n===''||!Number.isInteger(n))){error.value='请填写明确的合成价格、取消界线、佣金和缓冲期，并确认仅用于演练。';return;}
 const store=props.session.state.storeId,body:Schema['ServiceTermsInput']={service_id:selectedService.value,currency:'CNY',amount_fen:Number(amount.value),billing_unit:'WHOLE_SLOT',cancel_cutoff_minutes:Number(cutoff.value),consumer_late_cancel:'MANUAL_REVIEW',merchant_cancel:'FULL_REFUND',no_show:'MANUAL_REVIEW',commission_basis_points:Number(rate.value),settlement_buffer_minutes:Number(buffer.value),evidence_refs:[{kind:'TEST_SCENARIO',reference:'TEST_ONLY_MERCHANT_UI'}]};
 await command(JSON.stringify(['draft',store,body]),async key=>unwrap(await props.session.client.api.POST('/merchant/stores/{store_id}/service-trade-terms',{params:{path:{store_id:store},header:mutationHeaders(key)},body})));}
async function review(t:Terms,approve:boolean){const body:Schema['TermsReviewInput']={decision:approve?'APPROVE_SIMULATION':'REJECT',reason_code:approve?'TEST_SCENARIO_REVIEWED':'RULES_INCOMPLETE'};await command(JSON.stringify(['review',t.id,t.version,body]),key=>verified('service.terms.review',async proof=>unwrap(await props.session.client.api.POST('/admin/service-trade-terms/{id}/review',{params:{path:{id:t.id},header:mutationHeaders(key,proof,t.version)},body}))));}
async function cancel(t:Trade){const store=props.session.state.storeId;await command(`cancel:${t.id}:${t.version}`,async key=>unwrap(await props.session.client.api.POST('/merchant/stores/{store_id}/service-trade-orders/{id}/cancel',{params:{path:{store_id:store,id:t.id},header:mutationHeaders(key,undefined,t.version)},body:{reason_code:'SERVICE_UNAVAILABLE'}})));}
async function fulfill(t:Trade,status:Fulfillment['status']){if(status==='EXCEPTION'&&!reasons.value[t.id]){error.value='请选择具体异常原因。';return;}const store=props.session.state.storeId,body:Fulfillment={status,credential:status==='CHECKED_IN'?credentials.value[t.id]??'':'',reason_code:status==='EXCEPTION'?reasons.value[t.id]??'SERVICE_UNAVAILABLE':''};await command(JSON.stringify(['fulfill',t.id,t.version,body]),async key=>unwrap(await props.session.client.api.POST('/merchant/stores/{store_id}/service-trade-orders/{id}/fulfillment',{params:{path:{store_id:store,id:t.id},header:mutationHeaders(key,undefined,t.version)},body})));}
async function detail(t:Trade,kind:'history'|'disputes',more=false){if(busy.value)return;const current=stamp(),store=props.session.state.storeId,tag=`${kind}:${t.id}`,query={limit:50,...more&&detailCursors.value[tag]?{cursor:detailCursors.value[tag]!}:{}};busy.value=true;error.value='';
 try{if(kind==='history'){const r=unwrap(await props.session.client.api.GET('/merchant/stores/{store_id}/service-trade-orders/{id}/fulfillment',{params:{path:{store_id:store,id:t.id},query}}));if(current()){histories.value[t.id]=(more?[...histories.value[t.id]??[],...r.data]:r.data).sort((a,b)=>a.version-b.version);detailCursors.value[tag]=r.page.next_cursor;}}
 else{const r=props.realm==='admin'?unwrap(await props.session.client.api.GET('/admin/service-trade-orders/{id}/disputes',{params:{path:{id:t.id},query}})):unwrap(await props.session.client.api.GET('/merchant/stores/{store_id}/service-trade-orders/{id}/disputes',{params:{path:{store_id:store,id:t.id},query}}));if(current()){disputes.value[t.id]=more?[...disputes.value[t.id]??[],...r.data]:r.data;detailCursors.value[tag]=r.page.next_cursor;}}
 }catch(e){if(current())reportError(e);}finally{if(current())busy.value=false;}}
async function assess(t:Trade){if(busy.value)return;const current=stamp(),key=keys.get(`assessment:${t.id}:${t.version}`)??crypto.randomUUID();keys.set(`assessment:${t.id}:${t.version}`,key);busy.value=true;error.value='';try{const r=unwrap(await props.session.client.api.POST('/admin/service-trade-orders/{id}/refund-assessments',{params:{path:{id:t.id},header:mutationHeaders(key,undefined,t.version)},body:{}}));if(current()){assessment.value=r.data;keys.delete(`assessment:${t.id}:${t.version}`);}}catch(e){if(current())reportError(e);}finally{if(current())busy.value=false;}}
async function decide(t:Trade,approve:boolean){const snap=assessment.value;if(!snap||snap.trade_id!==t.id)return;const body:Schema['RefundDecisionInput']={assessment_id:snap.id,decision:approve?'APPROVE':'REJECT',reason_code:approve?'SNAPSHOT_RULES_APPLY':'EVIDENCE_INSUFFICIENT'};await command(JSON.stringify(['refund',t.id,t.version,body]),key=>verified('service.trade.refund.review',async proof=>unwrap(await props.session.client.api.POST('/admin/service-trade-orders/{id}/refund-decisions',{params:{path:{id:t.id},header:mutationHeaders(key,proof,t.version)},body}))));}
async function resolve(t:Trade,d:Schema['ServiceTradeDispute']){const body:Schema['ServiceTradeDisputeDecisionInput']={decision:'RESOLVE_NO_FINANCIAL_CHANGE',reason_code:'TEST_SCENARIO_REVIEWED',evidence_refs:[{kind:'TEST_SCENARIO',reference:'TEST_ONLY_PLATFORM_UI'}]};await command(JSON.stringify(['dispute',t.id,d.id,t.version]),key=>verified('service.trade.dispute.review',async proof=>unwrap(await props.session.client.api.POST('/admin/service-trade-orders/{id}/disputes/{dispute_id}/decisions',{params:{path:{id:t.id,dispute_id:d.id},header:mutationHeaders(key,proof,t.version)},body}))));}
async function previewSettlement(){if(busy.value)return;const current=stamp(),merchant=merchantId.value.trim();busy.value=true;error.value='';preview.value=undefined;reconciliation.value=undefined;try{const p=unwrap(await props.session.client.api.POST('/admin/merchants/{merchant_id}/service-trade-settlement-previews',{params:{path:{merchant_id:merchant},header:mutationHeaders(crypto.randomUUID())},body:{}}));const r=unwrap(await props.session.client.api.GET('/admin/merchants/{merchant_id}/service-trade-reconciliation',{params:{path:{merchant_id:merchant}}}));if(current()){preview.value=p.data;reconciliation.value=r.data;}}catch(e){if(current())reportError(e);}finally{if(current())busy.value=false;}}
async function settle(){const p=preview.value,current=stamp();if(!p||!p.eligible)return;await command(`settle:${p.id}:${p.ledger_sha256}`,key=>verified('service.trade.settle',async proof=>{const result=unwrap(await props.session.client.api.POST('/admin/merchants/{merchant_id}/service-trade-settlements',{params:{path:{merchant_id:p.merchant_id},header:mutationHeaders(key,proof)},body:{preview_id:p.id,accepted_ledger_sha256:p.ledger_sha256}}));if(current()){preview.value=undefined;reconciliation.value=undefined;}const reread=unwrap(await props.session.client.api.GET('/admin/merchants/{merchant_id}/service-trade-reconciliation',{params:{path:{merchant_id:p.merchant_id}}}));if(current())reconciliation.value=reread.data;return result;}));}
async function more(kind:'terms'|'trades'|'ledger'|'services'){const current=stamp();if(busy.value)return;busy.value=true;try{await(kind==='terms'?loadTerms(true):kind==='trades'?loadTrades(true):kind==='services'?loadServices(true):loadLedger(true));}catch(e){if(current())reportError(e);}finally{if(current())busy.value=false;}}
watch(()=>[props.session.state.principal?.session_id,props.session.state.storeId,permissions()],()=>{reset();void load();});onMounted(()=>{void load();});onBeforeUnmount(reset);
</script>
<template>
 <div v-if="blocked"><p role="status">{{ error }}</p><button :disabled="busy" @click="load">重新读取付费服务配置</button></div><section v-else aria-label="付费服务交易演练">
 <h2>付费服务交易演练</h2><p>仅合成条款与模拟收退款、履约和结算，不代表真实门店承诺或实际资金划付。</p>
 <p v-if="error" role="alert" class="error">{{ error }}。请刷新核对最新状态后再操作。</p><p v-if="notice" role="status">{{ notice }}</p><button class="secondary" :disabled="busy" @click="load">刷新付费服务</button>
 <template v-if="realm==='merchant'&&session.can('service.terms.write')">
  <form @submit.prevent="draft">
<fieldset :disabled="busy">
<legend>新增合成服务条款</legend>
  <label>服务<select v-model="selectedService" required><option value="" disabled>请选择服务</option><option v-for="s in services" :key="s.id" :value="s.id">{{ s.title }}</option></select></label>
  <button v-if="serviceCursor" type="button" class="secondary" :disabled="busy" @click="more('services')">更多可配置服务</button><label>整时段价格（分）<input v-model.number="amount" type="number" min="1" max="1000000000" required /></label><label>取消界线（开始前分钟）<input v-model.number="cutoff" type="number" min="0" max="129600" required /></label>
  <label>合成佣金（基点，100 基点为 1%）<input v-model.number="rate" type="number" min="0" max="10000" required /></label><label>完成后缓冲（分钟）<input v-model.number="buffer" type="number" min="0" max="129600" required /></label>
  <p>界线外按规则全退；界线内、开始后、已到店或未到店需人工评估。商家在服务开始前取消按已冻结合成规则全退。没有自动扣罚规则。</p><label><input v-model="scenario" type="checkbox" required />确认仅为合成工程案例，不作为真实商业政策</label><button>保存合成条款草稿</button>
  </fieldset>
</form>
 </template>
 <template v-if="realm==='admin'"><label v-if="session.can('service.terms.review')||session.can('service.trade.refund.review')||session.can('service.trade.dispute.review')||session.can('service.trade.settle')">敏感操作再次验证密码<input v-model="password" type="password" autocomplete="current-password" :disabled="busy" /></label></template>
 <article v-for="t in terms" :key="t.id" class="confirm-card"><h3>{{ t.service_title }} · {{ labels[t.state]??t.state }}</h3><p>{{ money(t.amount_fen) }} · 取消界线 {{ t.cancel_cutoff_minutes }} 分钟 · 合成佣金 {{ t.commission_basis_points }} 基点 · 缓冲 {{ t.settlement_buffer_minutes }} 分钟</p><p>条款编号 {{ t.id }}</p><template v-if="realm==='admin'&&t.state==='DRAFT'&&session.can('service.terms.review')"><button :disabled="busy||!password" @click="review(t,true)">审核通过合成条款</button><button class="secondary" :disabled="busy||!password" @click="review(t,false)">拒绝条款</button></template></article>
 <button v-if="termCursor" :disabled="busy" @click="more('terms')">更多条款</button>
 <form v-if="realm==='admin'&&session.can('service.trade.admin.read')" @submit.prevent="load"><label>服务交易编号<input v-model="lookup" required maxlength="36" :disabled="busy" /></label><button :disabled="busy">读取服务交易</button></form>
 <article v-for="t in trades" :key="t.id" class="confirm-card">
<h3>服务交易 {{ t.id }}</h3><p>预约开始 {{ new Date(t.starts_at).toLocaleString() }}</p><p>{{ labels[t.order_state]??t.order_state }} · {{ labels[t.fulfillment_state]??t.fulfillment_state }} · {{ labels[t.settlement_state]??t.settlement_state }}</p><p>应付 {{ money(t.payable_fen) }} · 已收 {{ money(t.paid_fen) }} · 已退 {{ money(t.refunded_fen) }} · 退款处理中 {{ money(t.refund_reserved_fen) }}</p><p>原佣金 {{ money(t.commission_fen) }} · 已冲佣 {{ money(t.commission_reversed_fen) }} · 交易净额 {{ money(t.merchant_net_fen) }}（非可提现余额）</p><p v-if="t.open_dispute">争议处理中，履约与结算冻结；处理争议不代表退款决定。</p>
  <template v-if="realm==='merchant'">
   <button v-if="session.can('service.trade.cancel')&&['AWAITING_PAYMENT','CONFIRMED'].includes(t.order_state)&&t.fulfillment_state==='NOT_STARTED'" class="secondary" :disabled="busy" @click="cancel(t)">因服务不可用取消交易</button>
   <button v-if="session.can('service.trade.read')" class="secondary" :disabled="busy" @click="detail(t,'history')">读取付费履约记录</button>
   <template v-if="session.can('service.trade.fulfill')&&t.order_state==='CONFIRMED'&&!t.open_dispute"><template v-if="t.fulfillment_state==='NOT_STARTED'"><label>消费者出示的付费服务凭证<input v-model="credentials[t.id]" maxlength="64" autocomplete="off" :disabled="busy" /></label><button :disabled="busy||!credentials[t.id]" @click="fulfill(t,'CHECKED_IN')">确认付费服务到店</button><button class="secondary" :disabled="busy" @click="fulfill(t,'NO_SHOW')">记录未到店</button></template><button v-if="t.fulfillment_state==='CHECKED_IN'" :disabled="busy" @click="fulfill(t,'COMPLETED')">确认付费服务完成</button><template v-if="['NOT_STARTED','CHECKED_IN'].includes(t.fulfillment_state)"><label>异常原因<select v-model="reasons[t.id]" :disabled="busy"><option value="" disabled>请选择异常原因</option><option value="SERVICE_UNAVAILABLE">服务不可用</option><option value="SAFETY_STOP">安全中止</option><option value="CUSTOMER_DISPUTE">消费者异议</option></select></label><button class="secondary" :disabled="busy||!reasons[t.id]" @click="fulfill(t,'EXCEPTION')">记录付费服务异常</button></template></template>
  </template>
  <button v-if="session.can(realm==='merchant'?'service.trade.dispute.read':'service.trade.dispute.review')" class="secondary" :disabled="busy" @click="detail(t,'disputes')">读取服务争议</button>
  <p v-for="h in histories[t.id]??[]" :key="h.id">{{ labels[h.status]??h.status }} · {{ h.occurred_at }}</p>
  <article v-for="d in disputes[t.id]??[]" :key="d.id"><p>争议 {{ d.id }} · {{ labels[d.state]??d.state }} · {{ d.reason_code }}</p><button v-if="realm==='admin'&&session.can('service.trade.dispute.review')&&d.state==='OPEN'" :disabled="busy||!password" @click="resolve(t,d)">记录已评估（不作资金变更）</button></article>
  <button v-if="detailCursors['history:'+t.id]" :disabled="busy" @click="detail(t,'history',true)">更多付费履约记录</button><button v-if="detailCursors['disputes:'+t.id]" :disabled="busy" @click="detail(t,'disputes',true)">更多服务争议</button>
  <template v-if="realm==='admin'&&session.can('service.trade.refund.assess')"><button class="secondary" :disabled="busy" @click="assess(t)">评估服务退款</button><div v-if="assessment?.trade_id===t.id"><p>评估金额 {{ money(assessment.proposed_refund_fen) }} · {{ assessment.eligible_for_approval?'符合冻结规则':'规则不足，不能批准' }} · 有效至 {{ assessment.expires_at }}</p><template v-if="session.can('service.trade.refund.review')"><button :disabled="busy||!password||!assessment.eligible_for_approval" @click="decide(t,true)">按有效快照批准退款</button><button class="secondary" :disabled="busy||!password" @click="decide(t,false)">保留拒绝记录</button></template></div></template>
 </article><button v-if="tradeCursor" :disabled="busy" @click="more('trades')">更多付费服务交易</button>
 <section v-if="realm==='merchant'&&session.can('service.trade.ledger.read')"><h3>门店服务流水</h3><p>仅已读取的流水；调整依据不重复计入余额。</p><p v-for="e in ledger" :key="e.id">{{ e.trade_id }} · {{ labels[e.entry_type]??e.entry_type }} · {{ labels[e.direction]??e.direction }} {{ money(e.amount_fen) }} · {{ e.affects_balance?'计入余额':'仅调整依据，不计余额' }}</p><button v-if="ledgerCursor" :disabled="busy" @click="more('ledger')">更多服务流水</button></section>
 <section v-if="realm==='admin'&&session.can('service.trade.settle')"><h3>服务模拟结算</h3><form @submit.prevent="previewSettlement"><label>商家编号<input v-model="merchantId" required maxlength="36" :disabled="busy" @input="preview=undefined;reconciliation=undefined" /></label><button :disabled="busy">获取结算预览与对账</button></form><p v-if="reconciliation">对账{{ reconciliation.consistent?'一致':'存在差异' }} · 商品余额 {{ money(reconciliation.goods_balance_fen) }} · 服务余额 {{ money(reconciliation.service_balance_fen) }} · 合计 {{ money(reconciliation.combined_balance_fen) }}</p><div v-if="preview"><p>本次模拟净额 {{ money(preview.net_fen) }} · 有效至 {{ preview.expires_at }}</p><p v-for="reason in preview.blocked_reasons" :key="reason">{{ labels[reason]??reason }}</p><button :disabled="busy||!password||!preview.eligible||!reconciliation?.consistent" @click="settle">验证并执行模拟结算</button></div></section>
 </section>
</template>
